import { trackShipment } from "./api/client";

const form = document.getElementById("f");
const input = document.getElementById("ref");
const out = document.getElementById("out");

form?.addEventListener("submit", async (event) => {
  event.preventDefault();
  out.textContent = "Looking up\u2026";

  try {
    const shipment = await trackShipment(input.value.trim());
    out.textContent = `${shipment.ref}\n${shipment.origin} \u2192 ${shipment.dest}\nStatus: ${shipment.status}`;
  } catch {
    out.textContent = "No shipment found for that reference.";
  }
});
