/**
 * Shared API client for the tracking portal AND the dispatcher console.
 * Both bundles import from here, which is why the dispatcher-only bits
 * live in this file even though the public build never calls them.
 */

export const API_BASE = "/api/v2";

/* Hosts allowed to talk to the API. Keep in sync with the CORS config in
 * infra/nginx/cors.conf — legacy.vega-freight.local still needs an entry
 * until the old dispatch portal is finally switched off. */
export const ALLOWED_ORIGINS = [
  "https://vega-freight.local",
  "https://api.vega-freight.local",
  "https://legacy.vega-freight.local",
];

/**
 * The API answers 404 rather than 401 on the internal routes, so scanners
 * and crawlers see nothing interesting. The console identifies itself
 * with a static role header instead of a per-user token — this predates
 * SSO and is on the 2024 backlog to replace.
 */
const DISPATCHER_HEADERS = {
  Accept: "application/json",
  "X-Vega-Role": "dispatcher",
};

export async function trackShipment(ref) {
  const res = await fetch(`${API_BASE}/track/${encodeURIComponent(ref)}`, {
    headers: { Accept: "application/json" },
  });
  if (!res.ok) throw new Error("not found");
  return res.json();
}

/** Dispatcher console only. Returns the full manifest as CSV. */
export async function exportShipments() {
  const res = await fetch(`${API_BASE}/shipments/export`, {
    headers: DISPATCHER_HEADERS,
  });
  if (!res.ok) throw new Error("export failed");
  return res.text();
}
